import { AndroidPermission, ManifestPermission, ManifestPermissionGroup } from '@droid/android';
import { Log, useProxyWatchUpdates, useTranslation } from '@fanfanlo';
import { Box, Checkbox, FormControlLabel, FormGroup, Typography } from '@mui/material';
import { useMemo } from 'react';

// 日志前缀
const LOG_PREFIX = '[AndroidPermissionsCheckbox]';
const fileLog = new Log(false, 'AndroidPermissionsCheckbox_f')
fileLog.pause = true;
fileLog.childrenPaused = true;
// 定义权限选项结构
interface PermissionOption {
  key: keyof typeof ManifestPermissionGroup | keyof typeof ManifestPermission;
  value: AndroidPermission;
  label: string; // 国际化后的权限说明
  group: 'ManifestPermissionGroup' | 'ManifestPermission';
}

interface IPermissionsProps {
  permissions: AndroidPermission[]; // 权限值数组
}

/**
 * 权限选择器组件 (Checkbox 版本)
 * @param props IPermissionsProps 对象 (使用 toProxy 包装)
 */
export const AndroidPermissionsCheckbox: React.FC<IPermissionsProps> = (props) => {
  fileLog.log(`${LOG_PREFIX} 组件初始化, props:`, props);

  const { t } = useTranslation('homepage/components/permissions/android-permissions/content');
  const { t: tManifest } = useTranslation('droid-android/android/components/content');

  // 监听 props.permissions 的变化,触发组件重新渲染
  const [permissions] = useProxyWatchUpdates(props, 'permissions', props.permissions);
  fileLog.log(`${LOG_PREFIX} permissions 数组长度: ${permissions.length}`);

  // 1. 构造用于显示的完整选项列表
  const permissionOptions: PermissionOption[] = useMemo(() => {
    fileLog.log(`${LOG_PREFIX} 开始构造权限选项列表`);
    const options: PermissionOption[] = [];

    // 1.1. 处理 ManifestPermissionGroup
    const groupKeys = Object.keys(ManifestPermissionGroup) as (keyof typeof ManifestPermissionGroup)[];
    fileLog.log(`${LOG_PREFIX} ManifestPermissionGroup 数量: ${groupKeys.length}`);

    groupKeys.forEach(key => {
      options.push({
        key: key,
        value: ManifestPermissionGroup[key] as AndroidPermission,
        label: tManifest(`Manifest.PermissionGroup.${key}`),
        group: 'ManifestPermissionGroup',
      });
    });

    // 1.2. 处理 ManifestPermission
    const permissionKeys = Object.keys(ManifestPermission) as (keyof typeof ManifestPermission)[];
    fileLog.log(`${LOG_PREFIX} ManifestPermission 数量: ${permissionKeys.length}`);

    permissionKeys.forEach(key => {
      options.push({
        key: key,
        value: ManifestPermission[key] as AndroidPermission,
        label: tManifest(`Manifest.Permission.${key}`),
        group: 'ManifestPermission',
      });
    });

    fileLog.log(`${LOG_PREFIX} 权限选项列表构造完成, 总数: ${options.length}`);
    return options;
  }, [tManifest]);

  // 2. 按分组整理选项
  const groupedOptions = useMemo(() => {
    fileLog.log(`${LOG_PREFIX} 开始按分组整理选项`);

    const groups = {
      ManifestPermissionGroup: [] as PermissionOption[],
      ManifestPermission: [] as PermissionOption[],
    };

    permissionOptions.forEach(option => {
      if (option.group === 'ManifestPermissionGroup') {
        groups.ManifestPermissionGroup.push(option);
      } else {
        groups.ManifestPermission.push(option);
      }
    });

    fileLog.log(`${LOG_PREFIX} 分组完成, ManifestPermissionGroup: ${groups.ManifestPermissionGroup.length}, ManifestPermission: ${groups.ManifestPermission.length}`);
    return groups;
  }, [permissionOptions]);

  // 3. 处理 Checkbox 勾选/取消勾选事件
  const handleCheckboxChange = (permissionValue: AndroidPermission, checked: boolean) => {
    fileLog.log(`${LOG_PREFIX} Checkbox 状态变化, 权限: ${permissionValue}, 是否勾选: ${checked}`);

    if (checked) {
      // 勾选: 添加到数组
      const alreadyExists = props.permissions.includes(permissionValue);
      fileLog.log(`${LOG_PREFIX} 准备添加权限, 是否已存在: ${alreadyExists}`);

      if (alreadyExists) {
        fileLog.log(`${LOG_PREFIX} 权限已存在, 无需添加`);
      } else {
        props.permissions.push(permissionValue);
        fileLog.log(`${LOG_PREFIX} 权限已添加, 当前数组长度: ${props.permissions.length}`);
      }
    } else {
      // 取消勾选: 从数组中移除
      const index = props.permissions.indexOf(permissionValue);
      fileLog.log(`${LOG_PREFIX} 准备移除权限, 索引位置: ${index}`);

      if (index === -1) {
        fileLog.log(`${LOG_PREFIX} 权限不存在于数组中, 无需移除`);
      } else {
        props.permissions.splice(index, 1);
        fileLog.log(`${LOG_PREFIX} 权限已移除, 当前数组长度: ${props.permissions.length}`);
      }
    }
  };

  // 4. 渲染分组
  const renderGroup = (groupName: 'ManifestPermissionGroup' | 'ManifestPermission') => {
    const options = groupedOptions[groupName];
    fileLog.log(`${LOG_PREFIX} 渲染分组: ${groupName}, 选项数量: ${options.length}`);

    const groupLabel = t(`AndroidPermissionsCheckbox.Group.${groupName}`);

    return (
      <Box key={groupName} sx={{ mb: 3 }}>
        <Typography variant="subtitle2" color="primary" sx={{ mb: 1, fontWeight: 'bold' }}>
          {groupLabel}
        </Typography>
        <FormGroup>
          {options.map(option => {
            const isChecked = permissions.includes(option.value);

            return (
              <FormControlLabel
                key={option.value}
                control={
                  <Checkbox
                    checked={isChecked}
                    onChange={e => {
                      const checked = e.target.checked;
                      fileLog.log(`${LOG_PREFIX} onChange 事件触发, 权限: ${option.value}, checked: ${checked}`);
                      handleCheckboxChange(option.value, checked);
                    }}
                  />
                }
                label={
                  <Box>
                    <Typography variant="body2" sx={{ fontWeight: 500, color: 'primary.main' }}>
                      {option.label}
                    </Typography>
                    <Typography variant="caption" color="text.secondary" sx={{ fontFamily: 'monospace' }}>
                      {option.value}
                    </Typography>
                  </Box>
                }
              />
            );
          })}
        </FormGroup>
      </Box>
    );
  };

  fileLog.log(`${LOG_PREFIX} 组件渲染`);

  return (
    <Box sx={{ width: '100%' }}>
      {renderGroup('ManifestPermissionGroup')}
      {renderGroup('ManifestPermission')}
    </Box>
  );
};
